"""Publish the full research notes as a searchable local reading guide."""
from pathlib import Path
import html
import json
import re
import markdown

ROOT=Path(__file__).resolve().parents[1]
source=(ROOT/"notes/use-cases.md").read_text(encoding="utf-8")
rows=[]
for line in source.splitlines():
    if re.match(r"\| \d+\. ",line):
        fields=[x.strip() for x in line.strip("|").split("|")]
        number=int(fields[0].split(".")[0])
        group="学习与教学" if number<=10 else "工作与培训" if number in [11,12,14,17,20] else "内容与传播"
        rows.append({"title":fields[0]+(" · 英语等外语" if number==6 else ""),"items":fields[1].split("；"),"method":fields[2],"group":group})
assert len(rows)==20 and sum(len(r["items"]) for r in rows)==100
articles=[]
for i,section in enumerate(source.split("\n## ")[1:]):
    title,body=section.split("\n",1)
    if title.startswith("二、"):continue
    rendered=markdown.markdown(body,extensions=["tables","fenced_code"])
    articles.append(f'<details id="reading-{i}"><summary>{html.escape(title)}</summary><div class="article">{rendered}</div></details>')

